import { ContractReviewClient } from "./ContractReviewClient"

export const metadata = {
  title: "契約審査 | 群青マテリアル 法務部",
  description:
    "法務部の契約審査担当者向けの契約書レビュー画面。条項ごとのリスク判定、相手方条文と当社修正案の対比、依頼元部署とのコメント、自社審査基準との突き合わせ、版の履歴、承認と締結可否判断に対応。",
}

// このファイルは Server Component。@gunjo/ui は client 境界（ContractReviewClient）側でのみ
// import している（RSC からのバレル import は adoption.md の既知不具合 #684 に触れるため）。
export default function ContractReviewPage() {
  return <ContractReviewClient />
