"use client"

import * as React from "react"
import {
  IconArrowsHorizontal,
  IconFileText,
  IconLayoutColumns,
  IconPencilPlus,
  IconTrash,
} from "@tabler/icons-react"
import {
  Alert,
  AlertDescription,
  AlertTitle,
  Badge,
  Button,
  EmptyState,
  SegmentedControl,
  cn,
} from "@gunjo/ui"
import { diffText, summarizeDiff, type DiffSegment } from "./diff"

/**
 * 相手方条文と当社修正案の対比表示。
 *
 * @gunjo/ui に「2つの文章を並べて差分表示する」コンポーネントが無いため自前。
 * 削除は <del>、追加は <ins> で意味づけし、色だけに頼らない（取り消し線／下線＋
 * スクリーンリーダー向けラベル）。
 */

const DEL_CLASS =
  "bg-destructive-subtle text-destructive-subtle-foreground line-through decoration-destructive/70 rounded-[2px] px-0.5"
const INS_CLASS =
  "bg-success-subtle text-success-subtle-foreground underline decoration-success/70 underline-offset-2 rounded-[2px] px-0.5"

function DiffRun({ segment }: { segment: DiffSegment }) {
  if (segment.kind === "del") {
    return (
      <del className={DEL_CLASS}>
        <span className="sr-only">［削除ここから］</span>
        {segment.text}
        <span className="sr-only">［削除ここまで］</span>
      </del>
    )
  }
  if (segment.kind === "ins") {
    return (
      <ins className={INS_CLASS}>
        <span className="sr-only">［追加ここから］</span>
        {segment.text}
        <span className="sr-only">［追加ここまで］</span>
      </ins>
    )
  }
  return <span>{segment.text}</span>
}

function DiffBody({
  segments,
  omit,
  className,
}: {
  segments: DiffSegment[]
  /** この種別の区間は描画しない（原文側では追加、修正案側では削除を落とす） */
  omit?: DiffSegment["kind"]
  className?: string
}) {
  return (
    <p
      className={cn(
        "text-sm leading-7 tracking-[0.01em] [text-align:justify] [word-break:break-word]",
        className
      )}
    >
      {segments
        .filter((segment) => segment.kind !== omit)
        .map((segment, index) => (
          <DiffRun key={`${segment.kind}-${index}`} segment={segment} />
        ))}
    </p>
  )
}

function TextPanel({
  heading,
  meta,
  children,
  tone = "neutral",
}: {
  heading: string
  meta: string
  children: React.ReactNode
  tone?: "neutral" | "ours"
}) {
  const headingId = React.useId()
  return (
    <section
      aria-labelledby={headingId}
      className={cn(
        "min-w-0 rounded-md border bg-card",
        tone === "ours" ? "border-primary/40" : "border-border"
      )}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 border-b border-border bg-muted/40 px-3 py-2">
        <h5 id={headingId} className="text-sm font-semibold">
          {heading}
        </h5>
        <span className="text-xs text-muted-foreground">{meta}</span>
      </div>
      <div className="px-3 py-3">{children}</div>
    </section>
  )
}

export interface ClauseDiffViewProps {
  clauseLabel: string
  original: string
  revised: string
  originalMeta: string
  revisedMeta: string
  onStartDraft?: () => void
}

export function ClauseDiffView({
  clauseLabel,
  original,
  revised,
  originalMeta,
  revisedMeta,
  onStartDraft,
}: ClauseDiffViewProps) {
  const [mode, setMode] = React.useState("side")
  const segments = React.useMemo(
    () => (revised ? diffText(original, revised) : []),
    [original, revised]
  )
  const summary = React.useMemo(() => summarizeDiff(segments), [segments])

  // 修正案そのものが無い（未着手）
  if (!revised) {
    return (
      <div className="space-y-4">
        <TextPanel heading="相手方から届いた条文" meta={originalMeta}>
          <p className="text-sm leading-7 [text-align:justify]">{original}</p>
        </TextPanel>
        <EmptyState
          headingLevel={5}
          icon={<IconPencilPlus className="h-6 w-6" aria-hidden />}
          title="修正案はまだ作成されていません"
          description={`${clauseLabel}は審査未着手です。自社基準との対比を確認したうえで修正案を起案してください。`}
          action={
            <Button size="sm" onClick={onStartDraft}>
              修正案を起案する
            </Button>
          }
        />
      </div>
    )
  }

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-2">
          {summary.changed ? (
            <>
              <Badge
                variant="destructive"
                size="sm"
                icon={<IconTrash className="h-3 w-3" aria-hidden />}
              >
                削除 {summary.deleted}文字
              </Badge>
              <Badge
                variant="success"
                size="sm"
                icon={<IconPencilPlus className="h-3 w-3" aria-hidden />}
              >
                追加 {summary.inserted}文字
              </Badge>
            </>
          ) : (
            <Badge
              variant="secondary"
              size="sm"
              icon={<IconFileText className="h-3 w-3" aria-hidden />}
            >
              原案から変更なし
            </Badge>
          )}
        </div>
        <SegmentedControl
          aria-label="条文の見比べ方"
          size="sm"
          value={mode}
          onValueChange={setMode}
          fullWidth={false}
          options={[
            {
              value: "side",
              label: "並べて",
              icon: <IconLayoutColumns className="h-3.5 w-3.5" aria-hidden />,
            },
            {
              value: "inline",
              label: "見え消し",
              icon: <IconArrowsHorizontal className="h-3.5 w-3.5" aria-hidden />,
            },
          ]}
        />
      </div>

      {!summary.changed && (
        <Alert variant="info" icon={<IconFileText className="h-4 w-4" aria-hidden />}>
          <AlertTitle>相手方原案どおりで合意しています</AlertTitle>
          <AlertDescription>
            この条項は当社ひな形と実質的な差異がないため、修正提案をしていません。
          </AlertDescription>
        </Alert>
      )}

      {mode === "side" ? (
        <div className="grid gap-3 lg:grid-cols-2">
          <TextPanel heading="相手方から届いた条文" meta={originalMeta}>
            <DiffBody segments={segments} omit="ins" />
          </TextPanel>
          <TextPanel heading="当社の修正案" meta={revisedMeta} tone="ours">
            <DiffBody segments={segments} omit="del" />
          </TextPanel>
        </div>
      ) : (
        <TextPanel
          heading="見え消し（削除と追加を1つの条文に重ねて表示）"
          meta={`${originalMeta} / ${revisedMeta}`}
          tone="ours"
        >
          <DiffBody segments={segments} />
        </TextPanel>
      )}

      <p className="text-xs text-muted-foreground">
        取り消し線が相手方条文からの削除、下線が当社の追加です。文字単位で比較しています。
      </p>
    </div>
  )
}

