import type { CommentThreadItem } from "./data"

/**
 * 条項ごとのコメントスレッド（法務部 ↔ 依頼元部署）。
 *
 * @gunjo/ui の ChatMessage は AI チャット用（role が assistant / user / system で、
 * user 側は右寄せの吹き出しになる）ため、業務コメント＋返信＋解決済みの表現には
 * 使えなかった。ここでは PersonCell / Badge / Textarea / Button を組み合わせて自前で構成している。
 */

export interface CommentThreadProps {
  threads: CommentThreadItem[]
  clauseLabel: string
  currentUser: { name: string; role: string }
  onReply: (threadId: string, body: string) => void
  onToggleResolved: (threadId: string) => void
  onCreate: (body: string) => void
}

function sideVariant(side: CommentThreadItem["side"]) {
  return side === "法務部" ? "info" : "secondary"
}

export function CommentThread({
  threads,
  clauseLabel,
  currentUser,
  onReply,
  onToggleResolved,
  onCreate,
}: CommentThreadProps) {
  const [filter, setFilter] = React.useState("open")
  const [replyingTo, setReplyingTo] = React.useState<string | null>(null)
  const [replyBody, setReplyBody] = React.useState("")
  const [newBody, setNewBody] = React.useState("")

  const visible = React.useMemo(() => {
    if (filter === "resolved") return threads.filter((t) => t.resolved)
    if (filter === "open") return threads.filter((t) => !t.resolved)
    return threads
  }, [threads, filter])

  const openCount = threads.filter((t) => !t.resolved).length
  const resolvedCount = threads.length - openCount

  return (
    <div className="space-y-4">
      <SegmentedControl
        aria-label="コメントの表示範囲"
        size="sm"
        value={filter}
        onValueChange={(value) => {
          setFilter(value)
          setReplyingTo(null)
        }}
        options={[
          { value: "open", label: `未解決 ${openCount}` },
          { value: "resolved", label: `解決済 ${resolvedCount}` },
          { value: "all", label: `すべて ${threads.length}` },
        ]}
      />

      {visible.length === 0 ? (
        <EmptyState
          headingLevel={5}
          icon={<IconMessage2 className="h-6 w-6" aria-hidden />}
          title={
            threads.length === 0
              ? "この条項にはまだコメントがありません"
              : "表示できるコメントがありません"
          }
          description={
            threads.length === 0
              ? `${clauseLabel}について依頼元部署に確認したいことがあれば、下の入力欄から書き込んでください。`
              : "絞り込みを「すべて」に切り替えると、解決済みのやり取りも表示されます。"
          }
        />
      ) : (
        <ul className="space-y-3">
          {visible.map((thread) => {
            const replyOpen = replyingTo === thread.id
            return (
              <li
                key={thread.id}
                className={cn(
                  "rounded-md border bg-card p-3",
                  thread.resolved ? "border-border opacity-90" : "border-border"
                )}
              >
                <div className="flex flex-wrap items-start justify-between gap-2">
                  <PersonCell
                    size="sm"
                    name={thread.author}
                    secondary={thread.role}
                    className="min-w-0"
                  />
                  <div className="flex flex-wrap items-center gap-1.5">
                    <Badge variant={sideVariant(thread.side)} size="sm">
                      {thread.side}
                    </Badge>
                    {thread.resolved && (
                      <Badge
                        variant="success"
                        size="sm"
                        icon={<IconCheck className="h-3 w-3" aria-hidden />}
                      >
                        解決済
                      </Badge>
                    )}
                    <time
                      className="text-xs tabular-nums text-muted-foreground"
                      dateTime={thread.at.replace(/\//g, "-").replace(" ", "T")}
                    >
                      {thread.at}
                    </time>
                  </div>
                </div>

                <p className="mt-2 text-sm leading-6 [text-align:justify]">{thread.body}</p>

                {thread.replies.length > 0 && (
                  <ul className="mt-3 space-y-3 border-l-2 border-border pl-3">
                    {thread.replies.map((reply) => (
                      <li key={reply.id}>
                        <div className="flex flex-wrap items-center gap-x-2 gap-y-0.5">
                          <IconCornerDownRight
                            className="h-3.5 w-3.5 shrink-0 text-muted-foreground"
                            aria-hidden
                          />
                          <span className="text-sm font-medium">{reply.author}</span>
                          <span className="text-xs text-muted-foreground">{reply.role}</span>
                          <time
                            className="text-xs tabular-nums text-muted-foreground"
                            dateTime={reply.at.replace(/\//g, "-").replace(" ", "T")}
                          >
                            {reply.at}
                          </time>
                        </div>
                        <p className="mt-1 text-sm leading-6 [text-align:justify]">
                          {reply.body}
                        </p>
                      </li>
                    ))}
                  </ul>
                )}

                <div className="mt-3 flex flex-wrap items-center gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => {
                      setReplyingTo(replyOpen ? null : thread.id)
                      setReplyBody("")
                    }}
                    aria-expanded={replyOpen}
                    aria-controls={`reply-${thread.id}`}
                  >
                    返信する
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => onToggleResolved(thread.id)}
                  >
                    {thread.resolved ? (
                      <>
                        <IconRotate className="h-3.5 w-3.5" aria-hidden />
                        未解決に戻す
                      </>
                    ) : (
                      <>
                        <IconCheck className="h-3.5 w-3.5" aria-hidden />
                        解決にする
                      </>
                    )}
                  </Button>
                </div>

                {replyOpen && (
                  <div id={`reply-${thread.id}`} className="mt-3 space-y-2">
                    <Textarea
                      label={`${thread.author} さんへの返信`}
                      rows={3}
                      value={replyBody}
                      maxLength={800}
                      showCount
                      placeholder="社内の検討結果や、依頼元への確認事項を書いてください。"
                      onChange={(event) => setReplyBody(event.target.value)}
                    />
                    <div className="flex flex-wrap items-center gap-2">
                      <Button
                        size="sm"
                        disabled={replyBody.trim().length === 0}
                        onClick={() => {
                          onReply(thread.id, replyBody.trim())
                          setReplyBody("")
                          setReplyingTo(null)
                        }}
                      >
                        返信を送信
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => {
                          setReplyingTo(null)
                          setReplyBody("")
                        }}
                      >
                        取消
                      </Button>
                      <span className="text-xs text-muted-foreground">
                        {currentUser.name}（{currentUser.role}）として投稿します
                      </span>
                    </div>
                  </div>
                )}
              </li>
            )
          })}
        </ul>
      )}

      <Separator />

      <div className="space-y-2">
        <Textarea
          label="新しいコメント"
          description="依頼元部署にも通知されます。交渉方針など社外に出せない内容は「法務部内メモ」を使ってください。"
          rows={3}
          value={newBody}
          maxLength={800}
          showCount
          placeholder={`${clauseLabel}について確認したいことを書いてください。`}
          onChange={(event) => setNewBody(event.target.value)}
        />
        <Button
          size="sm"
          disabled={newBody.trim().length === 0}
          onClick={() => {
            onCreate(newBody.trim())
            setNewBody("")
            setFilter("open")
          }}
        >
          <IconMessagePlus className="h-4 w-4" aria-hidden />
          コメントを投稿
        </Button>
      </div>
    </div>
  )
}

