function ContractReviewBody() {
  const [loading, setLoading] = React.useState(true)
  const [clauses, setClauses] = React.useState<Clause[]>(seedClauses)
  const [selectedId, setSelectedId] = React.useState<string | null>(null)
  const [detailLoading, setDetailLoading] = React.useState(false)
  const [riskFilter, setRiskFilter] = React.useState("all")
  const [checked, setChecked] = React.useState<string[]>(["chk-antisocial"])
  const [decision, setDecision] = React.useState("conditional")
  const [workflow, setWorkflow] = React.useState<WorkflowValue>({
    currentStageId: "reviewer",
    status: "in-progress",
    records: {},
  })
  const [cosign, setCosign] = React.useState<CoSignValue | undefined>(undefined)

  const headingRef = React.useRef<HTMLHeadingElement | null>(null)
  const listHeadingRef = React.useRef<HTMLHeadingElement | null>(null)

  // 案件データの初期読み込み
  React.useEffect(() => {
    const timer = window.setTimeout(() => setLoading(false), 600)
    return () => window.clearTimeout(timer)
  }, [])

  // 条項を選ぶたびに本文・履歴を取り直す想定
  React.useEffect(() => {
    if (!selectedId) return
    setDetailLoading(true)
    const timer = window.setTimeout(() => {
      setDetailLoading(false)
      headingRef.current?.focus()
    }, 320)
    return () => window.clearTimeout(timer)
  }, [selectedId])

  const selected = clauses.find((clause) => clause.id === selectedId) ?? null

  const riskCounts = React.useMemo(() => {
    const counts: Record<RiskLevel, number> = { 高: 0, 中: 0, 低: 0 }
    for (const clause of clauses) counts[clause.risk] += 1
    return counts
  }, [clauses])

  const untouched = clauses.filter((clause) => clause.status === "未着手").length
  const openComments = clauses.reduce(
    (total, clause) => total + clause.comments.filter((thread) => !thread.resolved).length,
    0
  )

  const visibleClauses = React.useMemo(() => {
    const list =
      riskFilter === "all"
        ? clauses
        : clauses.filter((clause) => clause.risk === riskFilter)
    return [...list].sort(
      (a, b) => riskOrder[a.risk] - riskOrder[b.risk] || a.number - b.number
    )
  }, [clauses, riskFilter])

  const updateClause = React.useCallback(
    (clauseId: string, updater: (clause: Clause) => Clause) => {
      setClauses((prev) =>
        prev.map((clause) => (clause.id === clauseId ? updater(clause) : clause))
      )
    },
    []
  )

  const handleStatusChange = (status: ClauseStatus) => {
    if (!selected) return
    updateClause(selected.id, (clause) => ({ ...clause, status }))
  }

  const handleReply = (threadId: string, body: string) => {
    if (!selected) return
    updateClause(selected.id, (clause) => ({
      ...clause,
      comments: clause.comments.map((thread) =>
        thread.id === threadId
          ? {
              ...thread,
              replies: [
                ...thread.replies,
                {
                  id: `${threadId}-r${thread.replies.length + 1}`,
                  author: reviewerName,
                  role: reviewerRole,
                  at: nowStamp(),
                  body,
                },
              ],
            }
          : thread
      ),
    }))
  }

  const handleToggleResolved = (threadId: string) => {
    if (!selected) return
    updateClause(selected.id, (clause) => ({
      ...clause,
      comments: clause.comments.map((thread) =>
        thread.id === threadId ? { ...thread, resolved: !thread.resolved } : thread
      ),
    }))
  }

  const handleCreateComment = (body: string) => {
    if (!selected) return
    const thread: CommentThreadItem = {
      id: `c-${selected.id}-${selected.comments.length + 1}-${Date.now()}`,
      author: reviewerName,
      role: reviewerRole,
      side: "法務部",
      at: nowStamp(),
      body,
      resolved: false,
      replies: [],
    }
    updateClause(selected.id, (clause) => ({
      ...clause,
      comments: [thread, ...clause.comments],
    }))
  }

