                  attestations={[
                    { id: "att-1", label: "高リスク条項（第4条・第7条・第12条）の修正案を確認した" },
                    { id: "att-2", label: "自社の契約審査基準との対比結果を確認した" },
                    { id: "att-3", label: "依頼元部署との未解決コメントが残っていないことを確認した" },
