// 条文の差分計算（相手方原案 ↔ 当社修正案）
// @gunjo/ui に文章の差分表示コンポーネントが無いため、この画面で自前実装している。
// 日本語の条文は語境界が取りにくいので、文字単位の LCS で差分を取り、
// 同種の連続を1つの区間にまとめて表示する。

export type DiffKind = "equal" | "del" | "ins"

export interface DiffSegment {
  kind: DiffKind
  text: string
}

/** 文字単位 LCS。条文1つは数百文字なので DP で十分。 */
export function diffText(before: string, after: string): DiffSegment[] {
  const a = Array.from(before)
  const b = Array.from(after)
  const n = a.length
  const m = b.length

  if (n === 0 && m === 0) return []
  if (n === 0) return [{ kind: "ins", text: after }]
  if (m === 0) return [{ kind: "del", text: before }]

  // dp[i][j] = a[i..] と b[j..] の LCS 長
  const width = m + 1
  const dp = new Uint32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i * width + j] =
        a[i] === b[j]
          ? dp[(i + 1) * width + (j + 1)] + 1
          : Math.max(dp[(i + 1) * width + j], dp[i * width + (j + 1)])
    }
  }

  const raw: DiffSegment[] = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      raw.push({ kind: "equal", text: a[i] })
      i++
      j++
    } else if (dp[(i + 1) * width + j] >= dp[i * width + (j + 1)]) {
      raw.push({ kind: "del", text: a[i] })
      i++
    } else {
      raw.push({ kind: "ins", text: b[j] })
      j++
    }
  }
  while (i < n) raw.push({ kind: "del", text: a[i++] })
  while (j < m) raw.push({ kind: "ins", text: b[j++] })

  // 同種の連続をまとめる
  const merged: DiffSegment[] = []
  for (const seg of raw) {
    const last = merged[merged.length - 1]
    if (last && last.kind === seg.kind) last.text += seg.text
    else merged.push({ ...seg })
  }
  return merged
}

export interface DiffSummary {
  deleted: number
  inserted: number
  changed: boolean
}

export function summarizeDiff(segments: DiffSegment[]): DiffSummary {
  let deleted = 0
  let inserted = 0
  for (const seg of segments) {
    if (seg.kind === "del") deleted += Array.from(seg.text).length
    if (seg.kind === "ins") inserted += Array.from(seg.text).length
  }
  return { deleted, inserted, changed: deleted > 0 || inserted > 0 }
}
